// ASP.NET Core minimal API (C#)
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddSingleton<IConnectionMultiplexer>(
    _ => ConnectionMultiplexer.Connect("localhost:6379"));
var app = builder.Build();

app.MapGet("/orders/{id}", async (string id, IConnectionMultiplexer mux) =>
{
    var db = mux.GetDatabase();
    var json = await db.StringGetAsync($"order:{id}");
    return json.IsNullOrEmpty ? Results.NotFound() : Results.Content(json!, "application/json");
});

app.Run("http://localhost:3000");

