public sealed class EmailQueueWorker(IAmazonSQS sqs) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            var resp = await sqs.ReceiveMessageAsync("https://sqs.../email", stoppingToken);
            foreach (var msg in resp.Messages)
                await ProcessEmailAsync(msg, stoppingToken);
        }
    }
}
